105→// GetAdditionalSessions implements SessionSource interface.
106→// Returns active sessions from .git/entire-sessions/ that haven't yet been condensed.
107→func (s *ManualCommitStrategy) GetAdditionalSessions(ctx context.Context) ([]*Session, error) {
108→	activeStates, err := s.listAllSessionStates(ctx)
109→	if err != nil {
110→		return nil, fmt.Errorf("failed to list session states: %w", err)
111→	}
112→
113→	if len(activeStates) == 0 {
114→		return nil, nil
115→	}
116→
117→	var sessions []*Session
118→	for _, state := range activeStates {
119→		session := &Session{
120→			ID:          state.SessionID,
121→			Description: NoDescription,
122→			Strategy:    StrategyNameManualCommit,
123→			StartTime:   state.StartedAt,
124→		}
125→
126→		// Try to get description from shadow branch
127→		if description := s.getDescriptionFromShadowBranch(ctx, state.SessionID, state.BaseCommit, state.WorktreeID); description != "" {
128→			session.Description = description
129→		}
130→
131→		sessions = append(sessions, session)
132→	}
133→
134→	return sessions, nil
135→}
