137→// getDescriptionFromShadowBranch reads the session description from the shadow branch.
138→// sessionID is expected to be an Entire session ID (already date-prefixed like "2026-01-12-abc123").
139→func (s *ManualCommitStrategy) getDescriptionFromShadowBranch(ctx context.Context, sessionID, baseCommit, worktreeID string) string {
140→	repo, err := OpenRepository(ctx)
141→	if err != nil {
142→		return ""
143→	}
144→
145→	shadowBranchName := getShadowBranchNameForCommit(baseCommit, worktreeID)
146→	refName := plumbing.NewBranchReferenceName(shadowBranchName)
147→	ref, err := repo.Reference(refName, true)
148→	if err != nil {
149→		return ""
150→	}
151→
152→	commit, err := repo.CommitObject(ref.Hash())
153→	if err != nil {
154→		return ""
155→	}
156→
157→	tree, err := commit.Tree()
158→	if err != nil {
159→		return ""
160→	}
161→
162→	// Use the session ID directly as the metadata directory name
163→	metadataDir := paths.SessionMetadataDirFromSessionID(sessionID)
164→	return getSessionDescriptionFromTree(tree, metadataDir)
165→}
