 66→// getCheckpointLog returns the transcript for a specific checkpoint ID.
 67→// Uses checkpoint.GitStore.ReadCommitted() for reading from entire/checkpoints/v1.
 68→func (s *ManualCommitStrategy) getCheckpointLog(ctx context.Context, checkpointID id.CheckpointID) ([]byte, error) {
 69→	store, err := s.getCheckpointStore()
 70→	if err != nil {
 71→		return nil, fmt.Errorf("failed to get checkpoint store: %w", err)
 72→	}
 73→
 74→	content, err := store.ReadLatestSessionContent(ctx, checkpointID)
 75→	if err != nil {
 76→		return nil, fmt.Errorf("failed to read checkpoint: %w", err)
 77→	}
 78→	if content == nil {
 79→		return nil, fmt.Errorf("checkpoint not found: %s", checkpointID)
 80→	}
 81→	if len(content.Transcript) == 0 {
 82→		return nil, fmt.Errorf("no transcript found for checkpoint: %s", checkpointID)
 83→	}
 84→
 85→	return content.Transcript, nil
 86→}
