 96→// CondenseSession condenses a session's shadow branch to permanent storage.
 97→// checkpointID is the 12-hex-char value from the Entire-Checkpoint trailer.
 98→// Metadata is stored at sharded path: <checkpoint_id[:2]>/<checkpoint_id[2:]>/
 99→// Uses checkpoint.GitStore.WriteCommitted for the git operations.
100→//
101→// For mid-session commits (no Stop/SaveStep called yet), the shadow branch may not exist.
102→// In this case, data is extracted from the live transcript instead.
103→func (s *ManualCommitStrategy) CondenseSession(ctx context.Context, repo *git.Repository, checkpointID id.CheckpointID, state *SessionState, committedFiles map[string]struct{}, opts ...condenseOpts) (*CondenseResult, error) {
104→	ag, _ := agent.GetByAgentType(state.AgentType) //nolint:errcheck // ag may be nil for unknown agent types; callers use type assertions so nil is safe
105→	var o condenseOpts
106→	if len(opts) > 0 {
107→		o = opts[0]
108→	}
109→
110→	// Get shadow branch — use pre-resolved ref if available, otherwise resolve from repo.
111→	shadowBranchName := getShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
112→	ref := o.shadowRef
113→	var hasShadowBranch bool
114→	if ref != nil {
115→		hasShadowBranch = true
116→	} else {
117→		refName := plumbing.NewBranchReferenceName(shadowBranchName)
118→		var err error
119→		ref, err = repo.Reference(refName, true)
120→		hasShadowBranch = err == nil
121→	}
122→
123→	var sessionData *ExtractedSessionData
124→	if hasShadowBranch {
125→		var extractErr error
126→		sessionData, extractErr = s.extractSessionData(ctx, repo, ref.Hash(), state.SessionID, state.FilesTouched, state.AgentType, state.TranscriptPath, state.CheckpointTranscriptStart, state.Phase.IsActive())
127→		if extractErr != nil {
128→			return nil, fmt.Errorf("failed to extract session data: %w", extractErr)
129→		}
130→	} else {
131→		if state.TranscriptPath == "" {
132→			return nil, errors.New("shadow branch not found and no live transcript available")
133→		}
134→		if state.Phase.IsActive() {
135→			prepareTranscriptIfNeeded(ctx, ag, state.TranscriptPath)
136→		}
137→		var extractErr error
138→		sessionData, extractErr = s.extractSessionDataFromLiveTranscript(ctx, state)
139→		if extractErr != nil {
140→			return nil, fmt.Errorf("failed to extract session data from live transcript: %w", extractErr)
141→		}
142→	}
143→
144→	// Backfill session state token usage from the freshly-extracted transcript.
145→	// Some agents (e.g., Copilot CLI) write aggregate token data (session.shutdown)
146→	// AFTER all hooks return, so state.TokenUsage from turn-end only has fallback data.
147→	// By condensation time, the transcript has the authoritative totals.
148→	// Only replace when we got authoritative data (e.g., session.shutdown provides
149→	// InputTokens; the fallback path only captures OutputTokens). This avoids
150→	// overwriting accumulated multi-checkpoint totals with partial checkpoint data.
151→	if sessionData.TokenUsage != nil && sessionData.TokenUsage.InputTokens > 0 {
152→		state.TokenUsage = sessionData.TokenUsage
153→	}
154→
155→	// For 1:1 checkpoint model: filter files_touched to only include files actually
156→	// committed in this specific commit. This ensures each checkpoint represents
157→	// exactly the files in that commit, not all files mentioned in the transcript.
158→	if len(committedFiles) > 0 {
