380→		}
381→
382→		// Check for checkpoint trailer
383→		if cpIDs := trailers.ParseAllCheckpoints(current.Message); len(cpIDs) > 0 {
384→			result.checkpointIDs = cpIDs
385→			result.commitHash = current.Hash.String()
386→			result.commitMessage = current.Message
387→			// Only warn about branch work commits, not merge commits
388→			result.newerCommitsExist = branchWorkCommits > 0
389→			result.newerCommitCount = branchWorkCommits
390→			return result
391→		}
392→
393→		// Only count regular commits (not merge commits) as "branch work"
394→		if current.NumParents() <= 1 {
395→			branchWorkCommits++
396→		}
397→
398→		totalChecked++
399→
400→		// Move to parent (first parent for merge commits - follows the main line)
401→		if current.NumParents() == 0 {
402→			break
403→		}
404→		parent, err := current.Parent(0)
405→		if err != nil {
406→			// Can't get parent, treat as end of history
407→			break
408→		}
409→		current = parent
410→	}
411→
412→	// No checkpoint found
413→	return result
414→}
415→
416→// promptResumeFromOlderCheckpoint asks the user if they want to resume from an older checkpoint.
417→func promptResumeFromOlderCheckpoint() (bool, error) {
418→	var confirmed bool
419→
420→	form := NewAccessibleForm(
421→		huh.NewGroup(
422→			huh.NewConfirm().
423→				Title("Resume from this older checkpoint?").
424→				Value(&confirmed),
425→		),
426→	)
427→
428→	if err := form.Run(); err != nil {
429→		if errors.Is(err, huh.ErrUserAborted) {
430→			return false, nil
431→		}
432→		return false, fmt.Errorf("failed to get confirmation: %w", err)
433→	}
434→
435→	return confirmed, nil
436→}
437→
438→// checkRemoteMetadata checks if checkpoint metadata exists on origin/entire/checkpoints/v1
439→// and automatically fetches it if available.
440→func checkRemoteMetadata(ctx context.Context, repo *git.Repository, checkpointID id.CheckpointID) error {
441→	// Try to get remote metadata branch tree
442→	remoteTree, err := strategy.GetRemoteMetadataBranchTree(repo)
443→	if err != nil {
444→		fmt.Fprintf(os.Stderr, "Checkpoint '%s' found in commit but session metadata not available\n", checkpointID)
445→		fmt.Fprintf(os.Stderr, "The entire/checkpoints/v1 branch may not exist locally or on the remote.\n")
446→		return nil //nolint:nilerr // Informational message, not a fatal error
447→	}
448→
449→	// Check if the checkpoint exists on the remote
450→	metadata, err := strategy.ReadCheckpointMetadata(remoteTree, checkpointID.Path())
451→	if err != nil {
452→		fmt.Fprintf(os.Stderr, "Checkpoint '%s' found in commit but session metadata not available\n", checkpointID)
453→		return nil //nolint:nilerr // Informational message, not a fatal error
454→	}
455→
456→	// Metadata exists on remote but not locally - fetch it automatically
457→	fmt.Fprintf(os.Stderr, "Fetching session metadata from origin...\n")
458→	if err := FetchMetadataBranch(ctx); err != nil {
459→		fmt.Fprintf(os.Stderr, "Failed to fetch metadata: %v\n", err)
460→		fmt.Fprintf(os.Stderr, "You can try manually: git fetch origin entire/checkpoints/v1:entire/checkpoints/v1\n")
461→		return NewSilentError(errors.New("failed to fetch metadata"))
462→	}
463→
464→	// Now resume the session with the fetched metadata
465→	return resumeSession(ctx, metadata, false)
466→}
467→
468→// resumeSession restores and displays the resume command for a specific session.
469→// For multi-session checkpoints, restores ALL sessions and shows commands for each.
470→// If force is false, prompts for confirmation when local logs have newer timestamps.
471→// The caller must provide the already-resolved checkpoint metadata to avoid redundant lookups
472→// and to support both local and remote metadata trees.
473→func resumeSession(ctx context.Context, metadata *strategy.CheckpointInfo, force bool) error {
474→	checkpointID := metadata.CheckpointID
475→	sessionID := metadata.SessionID
476→
477→	// Resolve agent from checkpoint metadata (same as rewind)
478→	ag, err := strategy.ResolveAgentForRewind(metadata.Agent)
479→	if err != nil {
480→		return fmt.Errorf("failed to resolve agent: %w", err)
481→	}
482→
483→	// Initialize logging context with agent
484→	logCtx := logging.WithAgent(logging.WithComponent(ctx, "resume"), ag.Name())
485→
486→	logging.Debug(logCtx, "resume session started",
487→		slog.String("checkpoint_id", checkpointID.String()),
488→		slog.String("session_id", sessionID),
489→	)
490→
491→	// Get worktree root for session directory lookup
492→	repoRoot, err := paths.WorktreeRoot(ctx)
493→	if err != nil {
494→		return fmt.Errorf("failed to get worktree root: %w", err)
495→	}
496→
497→	sessionDir, err := ag.GetSessionDir(repoRoot)
498→	if err != nil {
499→		return fmt.Errorf("failed to determine session directory: %w", err)
500→	}
501→
502→	// Create directory if it doesn't exist
503→	if err := os.MkdirAll(sessionDir, 0o700); err != nil {
504→		return fmt.Errorf("failed to create session directory: %w", err)
505→	}
506→
507→	// Get strategy and restore sessions using full checkpoint data
508→	strat := GetStrategy(ctx)
509→
510→	// Ensure transcript blobs are available locally before RestoreLogsOnly reads them.
511→	// After a treeless fetch, tree objects are present but full.jsonl blobs may not be.
512→	// This fetches only the specific blobs needed for this checkpoint.
513→	repo, repoErr := openRepository(ctx)
514→	if repoErr == nil {
515→		if blobErr := ensureTranscriptBlobs(ctx, repo, checkpointID); blobErr != nil {
516→			logging.Warn(logCtx, "failed to ensure transcript blobs, restore may fail",
517→				slog.String("error", blobErr.Error()),
518→			)
519→		}
520→	}
521→
522→	// Use RestoreLogsOnly via LogsOnlyRestorer interface for multi-session support
523→	// Create a logs-only rewind point with Agent populated (same as rewind)
524→	point := strategy.RewindPoint{
525→		IsLogsOnly:   true,
526→		CheckpointID: checkpointID,
527→		Agent:        metadata.Agent,
528→	}
529→
530→	sessions, restoreErr := strat.RestoreLogsOnly(ctx, point, force)
531→	if restoreErr != nil || len(sessions) == 0 {
532→		// Fall back to single-session restore (e.g., old checkpoints without agent metadata)
533→		return resumeSingleSession(ctx, ag, sessionID, checkpointID, repoRoot, force)
534→	}
535→
536→	logging.Debug(logCtx, "resume session completed",
537→		slog.String("checkpoint_id", checkpointID.String()),
538→		slog.Int("session_count", len(sessions)),
539→	)
540→
541→	return displayRestoredSessions(sessions)
542→}
543→
544→// displayRestoredSessions sorts sessions by CreatedAt and prints resume commands.
545→func displayRestoredSessions(sessions []strategy.RestoredSession) error {
546→	sort.SliceStable(sessions, func(i, j int) bool {
547→		return sessions[i].CreatedAt.Before(sessions[j].CreatedAt)
548→	})
549→
550→	if len(sessions) > 1 {
551→		fmt.Fprintf(os.Stderr, "\nRestored %d sessions. To continue, run:\n", len(sessions))
552→	} else if len(sessions) == 1 {
553→		fmt.Fprintf(os.Stderr, "Session: %s\n", sessions[0].SessionID)
554→		fmt.Fprintf(os.Stderr, "\nTo continue this session, run:\n")
555→	}
556→
557→	for i, sess := range sessions {
558→		sessionAgent, err := strategy.ResolveAgentForRewind(sess.Agent)
559→		if err != nil {
560→			return fmt.Errorf("failed to resolve agent for session %s: %w", sess.SessionID, err)
561→		}
562→		cmd := sessionAgent.FormatResumeCommand(sess.SessionID)
563→
564→		isLast := i == len(sessions)-1
565→		switch {
566→		case len(sessions) > 1 && isLast && sess.Prompt != "":
567→			fmt.Fprintf(os.Stderr, "  %s  # %s (most recent)\n", cmd, sess.Prompt)
568→		case len(sessions) > 1 && isLast:
569→			fmt.Fprintf(os.Stderr, "  %s  # (most recent)\n", cmd)
570→		case sess.Prompt != "":
571→			fmt.Fprintf(os.Stderr, "  %s  # %s\n", cmd, sess.Prompt)
572→		default:
573→			fmt.Fprintf(os.Stderr, "  %s\n", cmd)
574→		}
575→	}
576→
577→	return nil
578→}
579→
580→// resumeSingleSession restores a single session (fallback when multi-session restore fails).
581→// Always overwrites existing session logs to ensure consistency with checkpoint state.
582→// If force is false, prompts for confirmation when local log has newer timestamps.
583→func resumeSingleSession(ctx context.Context, ag agent.Agent, sessionID string, checkpointID id.CheckpointID, repoRoot string, force bool) error {
584→	sessionLogPath, err := resolveTranscriptPath(ctx, sessionID, ag)
585→	if err != nil {
586→		return fmt.Errorf("failed to resolve transcript path: %w", err)
587→	}
588→
589→	if checkpointID.IsEmpty() {
590→		logging.Debug(ctx, "resume session: empty checkpoint ID",
591→			slog.String("checkpoint_id", checkpointID.String()),
592→		)
593→		fmt.Fprintf(os.Stderr, "Session '%s' found in commit trailer but session log not available\n", sessionID)
594→		fmt.Fprintf(os.Stderr, "\nTo continue this session, run:\n")
595→		fmt.Fprintf(os.Stderr, "  %s\n", ag.FormatResumeCommand(sessionID))
596→		return nil
597→	}
598→
599→	logContent, _, err := checkpoint.LookupSessionLog(ctx, checkpointID)
600→	if err != nil {
601→		if errors.Is(err, checkpoint.ErrCheckpointNotFound) || errors.Is(err, checkpoint.ErrNoTranscript) {
602→			logging.Debug(ctx, "resume session completed (no metadata)",
603→				slog.String("checkpoint_id", checkpointID.String()),
604→				slog.String("session_id", sessionID),
605→			)
606→			fmt.Fprintf(os.Stderr, "Session '%s' found in commit trailer but session log not available\n", sessionID)
607→			fmt.Fprintf(os.Stderr, "\nTo continue this session, run:\n")
608→			fmt.Fprintf(os.Stderr, "  %s\n", ag.FormatResumeCommand(sessionID))
609→			return nil
610→		}
611→		logging.Error(ctx, "resume session failed",
612→			slog.String("checkpoint_id", checkpointID.String()),
613→			slog.String("session_id", sessionID),
614→			slog.String("error", err.Error()),
615→		)
616→		return fmt.Errorf("failed to get session log: %w", err)
617→	}
618→
619→	// Check if local file has newer timestamps than checkpoint
620→	if !force {
621→		localTime := paths.GetLastTimestampFromFile(sessionLogPath)
622→		checkpointTime := paths.GetLastTimestampFromBytes(logContent)
623→		status := strategy.ClassifyTimestamps(localTime, checkpointTime)
624→
625→		if status == strategy.StatusLocalNewer {
626→			sessions := []strategy.SessionRestoreInfo{{
627→				SessionID:      sessionID,
628→				Status:         status,
629→				LocalTime:      localTime,
630→				CheckpointTime: checkpointTime,
631→			}}
632→			shouldOverwrite, promptErr := strategy.PromptOverwriteNewerLogs(sessions)
633→			if promptErr != nil {
634→				return fmt.Errorf("failed to get confirmation: %w", promptErr)
635→			}
636→			if !shouldOverwrite {
637→				fmt.Fprintf(os.Stderr, "Resume cancelled. Local session log preserved.\n")
638→				return nil
639→			}
640→		}
641→	}
642→
643→	// Ensure parent directory exists
644→	if err := os.MkdirAll(filepath.Dir(sessionLogPath), 0o750); err != nil {
645→		return fmt.Errorf("failed to create session directory: %w", err)
646→	}
647→
648→	agentSession := &agent.AgentSession{
649→		SessionID:  sessionID,
650→		AgentName:  ag.Name(),
651→		RepoPath:   repoRoot,
652→		SessionRef: sessionLogPath,
653→		NativeData: logContent,
654→	}
655→
656→	// Write the session using the agent's WriteSession method
657→	if err := ag.WriteSession(ctx, agentSession); err != nil {
658→		logging.Error(ctx, "resume session failed during write",
659→			slog.String("checkpoint_id", checkpointID.String()),
660→			slog.String("session_id", sessionID),
661→			slog.String("error", err.Error()),
662→		)
663→		return fmt.Errorf("failed to write session: %w", err)
664→	}
665→
666→	logging.Debug(ctx, "resume session completed",
667→		slog.String("checkpoint_id", checkpointID.String()),
668→		slog.String("session_id", sessionID),
669→	)
670→
671→	fmt.Fprintf(os.Stderr, "Session restored to: %s\n", sessionLogPath)
672→	fmt.Fprintf(os.Stderr, "Session: %s\n", sessionID)
673→	fmt.Fprintf(os.Stderr, "\nTo continue this session, run:\n")
674→	fmt.Fprintf(os.Stderr, "  %s\n", ag.FormatResumeCommand(sessionID))
675→
676→	return nil
677→}
678→
679→func promptFetchFromRemote(branchName string) (bool, error) {
680→	var confirmed bool
681→
682→	form := NewAccessibleForm(
683→		huh.NewGroup(
684→			huh.NewConfirm().
685→				Title(fmt.Sprintf("Branch '%s' not found locally. Fetch from origin?", branchName)).
686→				Value(&confirmed),
687→		),
688→	)
689→
690→	if err := form.Run(); err != nil {
691→		if errors.Is(err, huh.ErrUserAborted) {
692→			return false, nil
693→		}
694→		return false, fmt.Errorf("failed to get confirmation: %w", err)
695→	}
696→
697→	return confirmed, nil
698→}
699→
700→// firstLine returns the first line of a string
701→func firstLine(s string) string {
702→	for i, c := range s {
703→		if c == '\n' {
704→			return s[:i]
705→		}
706→	}
707→	return s
708→}
