// ReadSessionPromptFromTree reads the first meaningful prompt from a checkpoint's prompt.txt file in a git tree.
// Returns an empty string if the prompt cannot be read.
func ReadSessionPromptFromTree(tree *object.Tree, checkpointPath string) string {
	promptPath := checkpointPath + "/" + paths.PromptFileName
	file, err := tree.File(promptPath)
	if err != nil {
		return ""
	}

	content, err := file.Contents()
	if err != nil {
		return ""
	}

	return ExtractFirstPrompt(content)
}

// ReadAgentTypeFromTree reads the agent type from a checkpoint's metadata.json file in a git tree.
// If metadata.json doesn't exist (shadow branches), it falls back to detecting the agent
// from the presence of agent-specific config files (.gemini/settings.json or .claude/).
// Returns agent.AgentTypeUnknown if the agent type cannot be determined.
func ReadAgentTypeFromTree(tree *object.Tree, checkpointPath string) types.AgentType {
	// First, try to read from metadata.json (present in condensed/committed checkpoints)
	metadataPath := checkpointPath + "/" + paths.MetadataFileName
	if file, err := tree.File(metadataPath); err == nil {

	checkpointID := result.checkpointIDs[0]

	// Multiple checkpoints (squash merge): resolve latest by CreatedAt timestamp.
	// resolveLatestCheckpoint also returns the metadata tree so we can reuse it
	// for the ReadCheckpointMetadata call below without a redundant lookup.
	var metadataTree *object.Tree
	if len(result.checkpointIDs) > 1 {
		latest, tree, err := resolveLatestCheckpoint(ctx, repo, result.checkpointIDs)
		if err != nil {
			// No metadata available — nothing to resume from
			fmt.Fprintf(os.Stderr, "Found %d checkpoints for commit %s but metadata is not available\n",
				len(result.checkpointIDs), result.commitHash[:7])
			return checkRemoteMetadata(ctx, repo, result.checkpointIDs[0])
		}
		skipped := len(result.checkpointIDs) - 1
		fmt.Fprintf(os.Stderr, "Found %d checkpoints for commit %s, resuming from the latest (%d older checkpoints skipped)\n",
			len(result.checkpointIDs), result.commitHash[:7], skipped)
		checkpointID = latest
		metadataTree = tree
	}

	// Get metadata branch tree for lookups (reuse from resolveLatestCheckpoint if available)
	if metadataTree == nil {
		var err error
		metadataTree, err = getMetadataTree(ctx, repo)
		if err != nil {
			// All fetch attempts failed, check if remote has it
			return checkRemoteMetadata(ctx, repo, checkpointID)
		}
	}

	// Ensure all checkpoint blobs are available locally before reading metadata.
	// After a treeless fetch, tree objects are present but blob content (metadata.json,
	// full.jsonl, etc.) may not be. This fetches all blobs for the checkpoint subtree.
	if blobErr := ensureCheckpointBlobs(ctx, repo, metadataTree, checkpointID); blobErr != nil {
		logging.Warn(ctx, "failed to ensure checkpoint blobs, reads may fail",
			slog.String("error", blobErr.Error()),
		)
	}

	// Look up metadata from sharded path
	metadata, err := strategy.ReadCheckpointMetadata(metadataTree, checkpointID.Path())
	if err != nil {
		// Checkpoint exists in commit but no local metadata - check remote
		return checkRemoteMetadata(ctx, repo, checkpointID)
	}

	return resumeSession(ctx, metadata, force)
}

