// The function navigates the sharded checkpoint directory structure:
//
//	<id[:2]>/<id[2:]>/
//	├── 0/
//	│   ├── full.jsonl          ← collected
//	│   ├── full.jsonl.001      ← collected (chunk)
//	│   └── metadata.json
//	├── 1/
//	│   └── full.jsonl          ← collected
//	└── metadata.json
