// Log tree details for diagnostics
var treeEntryNames []string
for _, e := range metadataTree.Entries {
	treeEntryNames = append(treeEntryNames, e.Name)
}
logging.Debug(logCtx, "metadata tree obtained, reading checkpoint",
	slog.String("checkpoint_id", checkpointID.String()),
	slog.String("checkpoint_path", checkpointID.Path()),
	slog.String("tree_hash", metadataTree.Hash.String()),
	slog.Int("tree_entry_count", len(metadataTree.Entries)),
	slog.Any("tree_entries", treeEntryNames),
)

// Wrap the metadata tree with on-demand blob fetching. After a treeless fetch,
// tree objects are local but blobs are not. The FetchingTree batch-fetches all
// missing blobs on first File() call.
// Use the fresh repo's storer (not the original repo) because a fetch may have
// created new packfiles that the original repo's storer doesn't know about.
ft := checkpoint.NewFetchingTree(ctx, metadataTree, freshRepo.Storer, FetchBlobsByHash)

// Look up metadata from sharded path (triggers blob fetch if needed)
metadata, err := strategy.ReadCheckpointMetadata(ft, checkpointID.Path())
if err != nil {
	logging.Warn(logCtx, "ReadCheckpointMetadata failed, checking remote",
		slog.String("checkpoint_id", checkpointID.String()),
		slog.String("checkpoint_path", checkpointID.Path()),
		slog.String("tree_hash", metadataTree.Hash.String()),
		slog.String("error", err.Error()),
	)
	// Checkpoint exists in commit but no local metadata - check remote
	return checkRemoteMetadata(ctx, checkpointID)
}

logging.Debug(logCtx, "checkpoint metadata read successfully",
	slog.String("checkpoint_id", checkpointID.String()),
	slog.String("session_id", metadata.SessionID),
	slog.Int("session_count", metadata.SessionCount),
)

return resumeSession(ctx, metadata, force)

